<?php
/**
 * Layout schemes for webinar blocks.
 *
 * Each block (timeline / takeaways / materials / details) has its own
 * set of built-in schemes or a custom CSS written by the user.
 *
 * @package Webinar_Block
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

/**
 * Stores and returns layout scheme CSS.
 */
class Webinar_Layouts {

	/**
	 * Block keys that support layout schemes.
	 *
	 * @return array
	 */
	public static function get_blocks() {
		return array( 'timeline', 'takeaways', 'materials', 'details' );
	}

	/**
	 * Scheme list for a specific block.
	 *
	 * @param string $block Block key.
	 * @return array
	 */
	public static function get_schemes( $block ) {
		$all = array(
			'timeline'  => array(
				'classic'  => __( 'Classic', 'webinar-block' ),
				'cards'    => __( 'Cards', 'webinar-block' ),
				'compact'  => __( 'Compact', 'webinar-block' ),
				'contrast' => __( 'Contrast', 'webinar-block' ),
				'custom'   => __( 'Custom', 'webinar-block' ),
			),
			'takeaways' => array(
				'classic'  => __( 'Classic', 'webinar-block' ),
				'accent'   => __( 'Accent', 'webinar-block' ),
				'gradient' => __( 'Gradient card', 'webinar-block' ),
				'custom'   => __( 'Custom', 'webinar-block' ),
			),
			'materials' => array(
				'classic'  => __( 'Classic', 'webinar-block' ),
				'accent'   => __( 'Accent', 'webinar-block' ),
				'gradient' => __( 'Gradient card', 'webinar-block' ),
				'custom'   => __( 'Custom', 'webinar-block' ),
			),
			'details'   => array(
				'classic' => __( 'Classic', 'webinar-block' ),
				'accent'  => __( 'Accent', 'webinar-block' ),
				'modern1' => __( 'Modern 1', 'webinar-block' ),
				'modern2' => __( 'Modern 2', 'webinar-block' ),
				'modern3' => __( 'Modern 3', 'webinar-block' ),
				'modern4' => __( 'Modern 4', 'webinar-block' ),
				'custom'  => __( 'Custom', 'webinar-block' ),
			),
		);
		return isset( $all[ $block ] ) ? $all[ $block ] : array();
	}

	/**
	 * Return preset CSS for a block + scheme.
	 *
	 * @param string $block  Block key.
	 * @param string $scheme Scheme key.
	 * @return string
	 */
	public static function get_css( $block, $scheme ) {
		$presets = self::presets();
		if ( isset( $presets[ $block ][ $scheme ] ) ) {
			return $presets[ $block ][ $scheme ];
		}
		return '';
	}

	/**
	 * Built-in scheme CSS.
	 *
	 * To add a new preset, add:
	 * 1. the translation to the function get_schemes( )
	 * 2. the preset to the array in the function presets()
	 * 3. the translation to the po and mo file
	 * The CSS must start with .webinar-widget — otherwise, str_replace won’t wrap it in [data-webinar-id], and the styles won’t be applied.
	 * Grid column switches must use @container webinar (min/max-width: Npx),
	 * NOT viewport @media — widgets can sit in narrow containers (tables,
	 * columns) where viewport width lies.
	 *
	 * All colors use CSS variables (--webinar-*) so schemes work with
	 * any color theme. User-written custom CSS uses relative selectors
	 * and is wrapped in a scope selector by instance_styles().
	 *
	 * @return array
	 */
	private static function presets() {
		return array(

			/*
			============================================================
			* TIMELINE.
			* ==========================================================
			*/
			'timeline'  => array(
				'classic'  => ".webinar-widget .webinar-timeline-list { list-style: none; padding: 0 0 0 5px; margin: 0; display: grid; grid-template-columns: 1fr; gap: 0 .8em; }\n.webinar-widget .webinar-timeline-item { display: grid; grid-template-columns: auto 1fr; column-gap: .6em; padding: .2em .2em .2em .4em; cursor: pointer; transition: background-color .2s ease; }\n.webinar-widget .webinar-timeline-link { display: contents; text-decoration: none; }\n.webinar-widget .webinar-timeline-link:hover .webinar-timeline-title,\n.webinar-widget .webinar-timeline-item:hover .webinar-timeline-title { color: var(--webinar-secondary, #3a7bc8); }\n.webinar-widget .webinar-timeline-time { grid-column: 1; grid-row: 1; font-weight: bold; color: var(--webinar-primary, #014993); font-variant-numeric: tabular-nums; font-size: .7em; }\n.webinar-widget .webinar-timeline-title { grid-column: 2; grid-row: 1; font-weight: 500; font-size: .75em; color: var(--webinar-accent, #002d5c); }\n.webinar-widget .webinar-timeline-desc { grid-column: 2; grid-row: 2; margin: .1em 0 0 0; color: var(--webinar-text-secondary, #555); font-size: .65em; line-height: 1.25; }\n.webinar-widget .webinar-timeline-item.webinar-timeline-active { background: var(--webinar-timeline-active, #c7e2fc); }\n.webinar-widget .webinar-timeline-link:focus { outline: none !important; box-shadow: none !important; border: none !important; }\n@media (max-width: 1199px) { .webinar-widget .webinar-timeline-list { width: 100%; padding: 10px 5px 0 5px; } }\n@media (max-width: 781px) { .webinar-widget .webinar-timeline-list { padding: 0; } }\n",

				'cards'    => ".webinar-widget .webinar-timeline-item { background: var(--webinar-bg-tile); border: 1px solid var(--webinar-border); border-radius: 8px; margin-bottom: 8px; padding: 8px 10px; }\n.webinar-widget .webinar-timeline-active { border-color: var(--webinar-primary); box-shadow: 0 2px 8px color-mix(in srgb, var(--webinar-primary) 10%, transparent); }\n",

				'compact'  => ".webinar-widget .webinar-timeline-item { padding: 2px 4px; }\n.webinar-widget .webinar-timeline-desc { display: none; }\n",

				'contrast' => ".webinar-widget .webinar-timeline-item { border-left: 3px solid var(--webinar-primary); padding-left: 10px; }\n.webinar-widget .webinar-timeline-time { background: var(--webinar-primary); color: var(--webinar-text-on-primary); padding: 2px 8px; border-radius: 4px; }\n",
			),

			/*
			============================================================
			* TAKEAWAYS.
			* ==========================================================
			*/
			'takeaways' => array(
				'classic'  => ".webinar-widget .webinar-key-takeaway { line-height: 1.25; font-weight: 500; color: var(--webinar-accent, #002d5c); padding-top: var(--wp--preset--spacing--30); padding-right: var(--wp--preset--spacing--20); padding-bottom: var(--wp--preset--spacing--30); padding-left: var(--wp--preset--spacing--20); font-size: var(--wp--preset--font-size--medium, 1rem); margin: 0px; }\n.webinar-widget .webinar-takeaways-grid { list-style: none; margin: 0; padding: 20px 10px; border-radius: 10px; display: grid; grid-template-columns: 1fr 1fr; gap: 12px; font-size: var(--wp--preset--font-size--medium, 18px); }\n.webinar-widget .webinar-takeaways-grid li, .webinar-widget .webinar-slider--takeaways .webinar-slider-slide > li { position: relative; margin: 0; padding: 1.2em .8em 1.2em 2.8em; background: var(--webinar-bg-tile, #fff); border: 1px solid var(--webinar-border, #e5e7eb); border-radius: 8px; list-style: none; color: var(--webinar-text-primary, #1e3a5f); box-shadow: 0 1px 3px rgba(0, 0, 0, .08); transition: all .3s ease; line-height: 1.25; }\n.webinar-widget .webinar-takeaways-grid li::before, .webinar-widget .webinar-slider--takeaways .webinar-slider-slide > li::before { content: \"\\2713\"; position: absolute; left: .9em; top: 50%; transform: translateY(-50%); width: 1.6em; height: 1.6em; border-radius: 50%; background: var(--webinar-badge-bg, #014993); border: 2px solid var(--webinar-badge-bg, #014993); color: var(--webinar-text-on-primary, #fff); font-size: .75em; font-weight: 700; display: flex; align-items: center; justify-content: center; box-sizing: border-box; }\n.webinar-widget .webinar-takeaways-grid li:hover, .webinar-widget .webinar-slider--takeaways .webinar-slider-slide > li:hover { transform: translateY(-3px); box-shadow: 0 8px 20px color-mix(in srgb, var(--webinar-primary, #014993) 15%, transparent); border-color: var(--webinar-primary, #014993); }\n@media (max-width: 782px) { .webinar-widget .webinar-takeaways-grid { padding: 15px 10px; } }\n@container webinar (max-width: 999px) { .webinar-widget .webinar-takeaways-grid { grid-template-columns: 1fr; } } @media (max-width: 600px) { .webinar-widget .webinar-takeaways-grid li, .webinar-widget .webinar-slider--takeaways .webinar-slider-slide > li { margin: 0 0 10px 0; } }\n",

				'accent'   => ".webinar-widget .webinar-takeaways-grid { list-style: none; margin: 0; background: color-mix(in srgb, var(--webinar-primary) 6%, transparent); padding: 20px 10px; border-radius: 12px; display: grid; grid-template-columns: 1fr 1fr; gap: 12px; border: 1px solid color-mix(in srgb, var(--webinar-primary) 20%, transparent); }\n.webinar-widget .webinar-takeaways-grid li { position: relative; margin: 0; padding: 1.2em 0.8em 1.2em 2.8em; background: var(--webinar-bg-tile); border: 1px solid color-mix(in srgb, var(--webinar-primary) 15%, transparent); border-radius: 8px; list-style: none; color: var(--webinar-text-primary); box-shadow: 0 2px 4px color-mix(in srgb, var(--webinar-primary) 8%, transparent); transition: all 0.3s ease; }\n.webinar-widget .webinar-takeaways-grid li::before { content: \"\\2713\"; position: absolute; left: 0.9em; top: 50%; transform: translateY(-50%); width: 1.6em; height: 1.6em; border-radius: 50%; background: var(--webinar-secondary); border: 2px solid var(--webinar-secondary); color: var(--webinar-text-on-primary); font-size: 0.75em; font-weight: 700; display: flex; align-items: center; justify-content: center; box-sizing: border-box; }\n.webinar-widget .webinar-takeaways-grid li:hover { transform: translateY(-3px); box-shadow: 0 8px 16px color-mix(in srgb, var(--webinar-secondary) 20%, transparent); border-color: var(--webinar-secondary); background: color-mix(in srgb, var(--webinar-primary) 4%, transparent); }\n@container webinar (max-width: 999px) { .webinar-widget .webinar-takeaways-grid { grid-template-columns: 1fr; } }\n",

				'gradient' => ".webinar-widget .webinar-takeaways-grid { list-style: none; margin: 0; padding: 20px 10px; border-radius: 10px; display: grid; grid-template-columns: 1fr 1fr; gap: 12px; font-size: var(--wp--preset--font-size--medium, 18px); }\n.webinar-widget .webinar-takeaways-grid li { position: relative; margin: 0; padding: 1.2em .8em 1.2em 2.8em; background: linear-gradient(135deg, var(--webinar-primary) 0%, var(--webinar-secondary) 100%); border: none; border-radius: 12px; list-style: none; color: var(--webinar-text-on-primary); box-shadow: 0 4px 12px color-mix(in srgb, var(--webinar-primary) 25%, transparent); transition: all .3s ease; line-height: 1.25; }\n.webinar-widget .webinar-takeaways-grid li::before { content: \"\\2713\"; position: absolute; left: .9em; top: 50%; transform: translateY(-50%); width: 1.6em; height: 1.6em; border-radius: 50%; background: color-mix(in srgb, var(--webinar-text-on-primary) 22%, transparent); border: 2px solid var(--webinar-text-on-primary); color: var(--webinar-text-on-primary); font-size: .75em; font-weight: 700; display: flex; align-items: center; justify-content: center; box-sizing: border-box; }\n.webinar-widget .webinar-takeaways-grid li:hover { transform: translateY(-3px); box-shadow: 0 12px 26px color-mix(in srgb, var(--webinar-primary) 35%, transparent); filter: brightness(1.05); }\n@container webinar (max-width: 999px) { .webinar-widget .webinar-takeaways-grid { grid-template-columns: 1fr; } }\n",
			),

			/*
			============================================================
			* MATERIALS.
			* ==========================================================
			*/
			'materials' => array(
				'classic'  => ".webinar-widget .webinar-materials-list { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }\n.webinar-widget .webinar-material-item { display: flex; align-items: center; flex-wrap: wrap; gap: 12px 16px; background: linear-gradient(var(--webinar-bg-tile), var(--webinar-bg-tile)) padding-box, linear-gradient(135deg, var(--webinar-primary), var(--webinar-secondary)) border-box; border: 1px solid transparent; border-radius: 8px; padding: 16px 20px; }\n.webinar-widget .webinar-material-desc { order: 1; flex: 1 1 240px; margin: 0; font-size: var(--wp--preset--font-size--medium, 1rem); line-height: 1.4; color: var(--webinar-text-secondary); }\n.webinar-widget .webinar-material-item .webinar-materials { order: 2; margin-left: auto; }\n@container webinar (max-width: 899px) { .webinar-widget .webinar-materials-list { grid-template-columns: 1fr; } }\n",

				'accent'   => ".webinar-widget .webinar-materials-list { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }\n.webinar-widget .webinar-material-item { display: flex; align-items: center; flex-wrap: wrap; gap: 12px 16px; background: color-mix(in srgb, var(--webinar-secondary) 8%, var(--webinar-bg-tile)); border: 1px solid color-mix(in srgb, var(--webinar-secondary) 30%, var(--webinar-border)); border-radius: 12px; padding: 16px 20px; }\n.webinar-widget .webinar-material-desc { order: 1; flex: 1 1 240px; margin: 0; font-size: var(--wp--preset--font-size--medium, 1rem); line-height: 1.4; color: var(--webinar-text-secondary); }\n.webinar-widget .webinar-material-item .webinar-materials { order: 2; margin-left: auto; }\n@container webinar (max-width: 899px) { .webinar-widget .webinar-materials-list { grid-template-columns: 1fr; } }\n",

