				'classic' => ".webinar-widget .webinar-content { margin-top: 1.2rem; }\n.webinar-widget .webinar-details-wrap { border: 1px solid var(--webinar-border, #e5e7eb); border-radius: 12px; background: linear-gradient(180deg, var(--webinar-bg-tile, #fff) 0%, var(--webinar-bg-content, #f9fafb) 100%); overflow: hidden; scroll-margin-top: 150px; }\n.webinar-widget .webinar-details-summary { display: flex; align-items: center; gap: .5em; cursor: pointer; font-weight: 400; list-style: none; user-select: none; -webkit-user-select: none; background: none; border: none; color: var(--webinar-accent, #002d5c); font-family: inherit; text-align: left; width: auto; justify-content: flex-end; letter-spacing: -.4px; padding-right: 24px; -webkit-tap-highlight-color: transparent; touch-action: manipulation; font-size: var(--wp--preset--font-size--medium, 1rem); }\n.webinar-widget .webinar-details-summary::-webkit-details-marker { display: none; }\n.webinar-widget .webinar-details-summary::marker { content: ''; }\n.webinar-widget .webinar-details-summary:hover { color: var(--webinar-secondary, #3a7bc8); }\n.webinar-widget .webinar-details-summary .webinar-chevron { transition: transform .25s ease; flex-shrink: 0; }\n.webinar-widget .webinar-details-wrap[open] > .webinar-details-summary .webinar-chevron { transform: rotate(180deg); }\n.webinar-widget .webinar-details-close .webinar-chevron { transform: rotate(180deg); }\n.webinar-widget .webinar-details-wrap[open].webinar-details-closing > .webinar-details-summary .webinar-chevron { transform: rotate(0deg); }\n.webinar-widget .webinar-details-summary:focus { outline: none !important; box-shadow: none !important; border: none !important; }\n.webinar-widget .webinar-details-body { padding: 28px 24px; overflow: hidden; }\n.webinar-widget .webinar-details-columns { column-gap: 2em; }\n.webinar-widget .webinar-detail-block { margin-bottom: 1.8em; padding: 20px; background: var(--webinar-bg-tile, #fff); border-radius: 10px; border: 1px solid var(--webinar-border, #e5e7eb); box-shadow: 0 1px 3px rgba(0, 0, 0, .04); transition: all .25s ease; }\n.webinar-widget .webinar-detail-block:hover { border-color: var(--webinar-secondary, #3a7bc8); box-shadow: 0 4px 12px color-mix(in srgb, var(--webinar-primary, #014993) 10%, transparent); transform: translateY(-2px); }\n.webinar-widget .webinar-detail-block h4 { font-size: 1.05em; margin: 0 0 .6em 0; color: var(--webinar-accent, #002d5c); font-weight: 600; display: flex; align-items: baseline; gap: .5em; }\n.webinar-widget .webinar-detail-time { display: inline-block; color: var(--webinar-text-inverse, #fff); font-weight: 700; font-variant-numeric: tabular-nums; background: var(--webinar-badge-bg, #014993); padding: 3px 10px; border-radius: 6px; font-size: .85em; line-height: 1.3; white-space: nowrap; user-select: none; -webkit-user-select: none; }\n.webinar-widget .webinar-detail-time-link { text-decoration: none; }\n.webinar-widget .webinar-detail-time:hover { opacity: 0.8; }\n.webinar-widget .webinar-detail-time-link:focus { outline: none; }\n.webinar-widget .webinar-detail-block p { margin: 0; font-size: var(--wp--preset--font-size--medium, 18px); line-height: 1.4; color: var(--webinar-text-secondary, #4b5563); }\n@container webinar (min-width: 900px) { .webinar-widget .webinar-details-columns { display: grid; grid-template-columns: 1fr 1fr; column-gap: 2em; } }\n@media (max-width: 780px) { .webinar-widget .webinar-details-body { padding: 20px 0; } .webinar-widget .webinar-details-wrap { border: none; } .webinar-widget .webinar-detail-block { padding: 16px; } }\n",
